import './styles.css';
import { CardItem } from '../cardItem/CardItem';
import { People, PeopleList } from '../../types/types';
import { Flyout } from '../flyout/flyout';
import { useRouter } from 'next/router';
import { useLocalStorage } from '../../hooks/useLocalStorage';
import { useEffect } from 'react';
import { pages } from 'next/dist/build/templates/app-page';

export function CardList({ peopleList, currentPage }: PeopleList) {
  const [savedSearch] = useLocalStorage();
  const router = useRouter();

  useEffect(() => {
    const queryString = savedSearch
      ? { search: savedSearch }
      : { page: currentPage };
    router.replace({
      pathname: router.pathname,
      query: queryString,
    });
  }, [savedSearch, currentPage]);

  return (
    <>
      {peopleList && peopleList.length > 0 ? (
        <ul className="cards-container">
          {peopleList.map((people: People) => (
            <CardItem people={people} key={people.name} />
          ))}
        </ul>
      ) : (
        <p className="no-results">Nothing found for your request</p>
      )}
      <Flyout />
    </>
  );
}
